  play:{lab:'Follow the whole story',hint:'The story plays page by page, from the first door',run:()=>{const c=$('#sbcover');if(c&&!c.hidden){click('#sbopen');return}if(window.ccLgOpen)window.ccLgOpen(0);later(()=>{const b=$('#lgplay');if(b&&b.textContent!=='Pause')b.click()},120)},at:'.lg'},
