/* ===== Wonderland redesign, round 5 (21 November 2026, Charlie) =====
   1. The title card a page keeps when its picture folds away has a little Wonderland vignette on its right, away from the words,
      a different one for each section and each story, made from the site's own cut-out pictures. It plays once when the card
      appears (a hop, a sway, a twinkle), then rests. Calm mode and reduced motion keep it still.
   2. Explore Wonderland's banner has its own moment, as lively as the chapters' ones: the White Rabbit bounds across the meadow
      and dives into the rabbit hole, playing cards tumble out after him, the hole glows and the key glints, and then the picture
      folds away as every picture does (Charlie's rule: show, play the moment, fold away by itself).
   3. A page turner at the end of every page: Home leads on to This Week, each section to the next, the last back to Home.
   This runs inside rd.js (it is joined onto its end at build time) and uses rd.js's helpers through window.ccRdKit. */
(function(){
const K=window.ccRdKit;if(!K)return;
const {esc,gar,SEC,RT,secs,secD,nartOf,picImg,artOf,ico}=K;
const W=o=>window[o]||{};
/* the cut-outs, looked up when a card is drawn (the page's own pictures, nothing new to fetch) */
const SRC={run:()=>W('SPRITES')['hare-running'],beckon:()=>W('IXA').beckon,leap:()=>W('IXA').leap,cat:()=>W('CHESHIRE').cat_s,
 bottle:()=>W('SPRITES')['drinkme-bottle'],cake:()=>W('SPRITES')['eatme-cake'],boards:()=>W('BANFX').boards,roseR:()=>W('BANFX').roseR,
 roseW:()=>W('BANFX').roseW,brush:()=>W('BANFX').brush,alice:()=>W('BANFX').alice,key:()=>W('CC_RD_IMG').key,lobster:()=>W('SCHOOLART').lobster,
 stairs:()=>W('SCHOOLART').stairs,gloves:()=>W('BANFX').gloves,fan:()=>W('BANFX').fan,dteapot:()=>W('SPRITES')['dormouse-teapot'],
 teacup:()=>W('SPRITES').teacup,hat:()=>W('SPRITES')['hat-whimsy'],cater:()=>W('SPRITES')['guest-caterpillar'],wave:()=>W('BANFX').cmrabbit,
 tarts:()=>W('SPRITES')['jam-tarts'],bat:()=>W('BANFX').bat,dormouse:()=>W('BANFX').dormouse,cloche:()=>W('SPRITES').cloche};
/* each vignette: its pieces [cut-out, left %, bottom %, height %, how it moves, delay in seconds] and its touches
   (sp: sparkles, pg: loose pages, ring: smoke rings, steam: steam, env: an invitation with a wax seal, bub: bubbles) */
const MO={
 'this-week':{p:[['run',14,2,92,'hop',.15]],t:['pg','sp']},
 'this-week/key-dates':{p:[['beckon',46,0,100,'sway',.15],['teacup',4,2,34,'bob',.45]],t:['sp']},
 'this-week/ignite':{p:[['wave',18,0,96,'sway',.15]],t:['pg','sp']},
 'roadmap':{p:[['boards',0,0,80,'sway',.1],['bottle',50,2,58,'bob',.4]],t:['sp']},
 'roadmap/horizon':{p:[['cat',2,10,58,'fade',.1]],t:['sp']},
 'ai-and-copilot':{p:[['cat',2,8,60,'fade',.1]],t:['sp']},
 'ai-and-copilot/caucus-race':{p:[['bat',14,30,56,'fly',.1]],t:['sp']},
 'ai-and-copilot/live-flowers':{p:[['roseW',0,0,70,'sway',.1],['roseR',30,0,80,'sway',.35]],t:['sp']},
 'ai-and-copilot/questions':{p:[['cater',12,0,100,'bob',.1]],t:['ring']},
 'governance':{p:[['roseW',0,0,66,'sway',.1],['roseR',24,0,76,'sway',.3],['brush',50,6,62,'paint',.5]],t:['sp']},
 'wonderland':{p:[['alice',0,0,86,'peek',.1],['key',72,40,40,'float',.5]],t:['sp']},
 'wonderland/tea-party':{p:[['hat',0,0,56,'bob',.1],['dteapot',30,0,66,'sway',.3],['teacup',70,0,32,'bob',.5]],t:['steam']},
 'wonderland/caterpillar':{p:[['cater',12,0,100,'bob',.1]],t:['ring']},
 'wonderland/rabbit-hole':{p:[['leap',6,26,60,'dive',.1],['key',74,4,34,'float',.5]],t:['sp']},
 'wonderland/hall-of-doors':{p:[['bottle',0,0,70,'bob',.1],['cake',40,0,50,'sway',.3],['key',76,38,36,'float',.5]],t:['sp']},
 'learning':{p:[['lobster',30,0,100,'dance',.1]],t:['bub']},
 'learning/school':{p:[['stairs',0,0,50,'none',0],['lobster',50,6,94,'dance',.2]],t:['bub']},
 'sources':{p:[['cloche',6,0,62,'bob',.1],['tarts',58,0,40,'sway',.35]],t:['sp']},
 'events':{p:[['fan',0,12,66,'sway',.35],['gloves',56,0,44,'bob',.55]],t:['env','sp']}};
const TOUCH={
 sp:'<i class="mo-sp s1"></i><i class="mo-sp s2"></i><i class="mo-sp s3"></i><i class="mo-sp s4"></i>',
 pg:'<i class="mo-pg g1"></i><i class="mo-pg g2"></i><i class="mo-pg g3"></i>',
 ring:'<i class="mo-ring r1"></i><i class="mo-ring r2"></i><i class="mo-ring r3"></i>',
 steam:'<i class="mo-steam t1"></i><i class="mo-steam t2"></i>',
 bub:'<i class="mo-bub b1"></i><i class="mo-bub b2"></i><i class="mo-bub b3"></i><i class="mo-bub b4"></i>',
 env:'<span class="mo-env"><svg viewBox="0 0 120 84" aria-hidden="true"><rect x="3" y="3" width="114" height="78" rx="7" fill="#fffaf2" stroke="#e3c98d" stroke-width="2.5"/><path d="M5 8l55 40 55-40" fill="none" stroke="#e3c98d" stroke-width="2.5" stroke-linejoin="round"/><path d="M5 78l40-32M115 78L75 46" fill="none" stroke="#efdcae" stroke-width="2"/><circle cx="60" cy="49" r="14" fill="#c4325a"/><circle cx="60" cy="49" r="10.5" fill="none" stroke="#e46b8b" stroke-width="1.6"/><path d="M60 55.5c-4.6-3.3-7-5.6-7-8.2 0-2 1.5-3.4 3.4-3.4 1.4 0 2.6.8 3.6 2.1 1-1.3 2.2-2.1 3.6-2.1 1.9 0 3.4 1.4 3.4 3.4 0 2.6-2.4 4.9-7 8.2z" fill="#ffd9e2"/></svg></span>'};
function motif(k){const key=MO[k]?k:(MO[String(k).split('/')[0]]?String(k).split('/')[0]:'');const m=MO[key];if(!m)return '';
 const ps=m.p.map(([s,l,b,h,mv,d])=>{const u=SRC[s]&&SRC[s]();if(!u)return '';
  return `<i class="mo-p" style="left:${l}%;bottom:${b}%;height:${h}%;--d:${d}s"><img class="mv-${mv}" src="${esc(u)}" alt="" decoding="async"></i>`}).join('');
 if(!ps)return '';
 return `<span class="rdmo rdmo-${esc(key.replace(/\//g,'-'))}" aria-hidden="true"><span class="rdmo-in">${(m.t||[]).map(t=>TOUCH[t]||'').join('')}${ps}</span></span>`}
K.motif=motif;

/* ---------- Explore Wonderland's banner moment ---------- */
/* the painting's own points (as shares of its width and height): the rabbit hole under the gum tree, and the key beside it */
const HOLE=[87.4,82],KEY=[89.6,82.4];
function hubFx(){const rab=W('IXA').leap;
 const card=(c,s)=>`<span class="hf-card ${c}"><b>${s}</b></span>`;
 return `<div class="rdhubfx" aria-hidden="true" style="--hx:${HOLE[0]}%;--hy:${HOLE[1]}%;--kx:${KEY[0]}%;--ky:${KEY[1]}%">
 ${Array.from({length:7},(_,i)=>`<i class="hf-leaf l${i+1}"></i>`).join('')}<span class="hf-glow"></span>${rab?`<span class="hf-runner"><img src="${esc(rab)}" alt="" decoding="async"></span>`:''}
 ${card('c1','\u2665')}${card('c2','\u2660')}${card('c3','\u2666')}${card('c4','\u2663')}
 <span class="hf-key"></span>${Array.from({length:12},(_,i)=>`<i class="hf-sp p${i+1}"></i>`).join('')}
 <div class="fxsay hf-say"><span>Oh my ears and whiskers, how late it\u2019s getting!</span></div></div>`}
K.banFx=sc=>sc==='glasshouse'?{ard:3.296,fy:.5,dur:8000,html:hubFx()}:null;

/* ---------- the page turner ---------- */
const ART={'':'clockmaker','this-week':'whitsundays','roadmap':'clockmaker','ai-and-copilot':'race','governance':'court2','wonderland':'glasshouse','learning':'school','events':'alice'};
const TPAL={'':1,'this-week':5,'roadmap':1,'ai-and-copilot':2,'governance':4,'wonderland':3,'learning':6,'events':4};
function turn(to,dir,lab,d){const sc=ART[to]||'',im=artOf(sc);
 return `<a class="rdturn rdk rdp${TPAL[to]||1} rdturn-${dir}" href="#/${to}"><span class="rdturn-art">${im?picImg(im,nartOf(sc)):''}</span><span class="rdturn-t"><small>${dir==='next'?'Next':'Back to'}</small><b>${esc(lab)}</b>${d?`<span>${esc(d)}</span>`:''}</span><span class="rdturn-go" aria-hidden="true">${dir==='next'?'\u2192':'\u2190'}</span></a>`}
function pager(k,virt){const r=RT[k]||{};if(r.xp)return '';
 const L=[''].concat(secs().map(s=>s.k)),s=k===''?'':(r.s||(k==='sources'?'learning':''));const i=L.indexOf(s);if(i<0)return '';
 const S=x=>SEC.find(z=>z.k===x)||{},front=k===''||k===s;
 const pv=front?(i>0?L[i-1]:null):s,nx=i<L.length-1?L[i+1]:'';
 const lab=x=>x===''?'Home':S(x).lab,dsc=x=>x===''?'The entrance to Wonderland: this issue at a glance.':secD(S(x));
 const a=pv!==null?turn(pv,'prev',lab(pv),dsc(pv)):'';
 const b=(nx!==''||k!=='')?turn(nx,'next',nx===''?'Back to the start':lab(nx),dsc(nx)):'';
 if(!a&&!b)return '';
 return `<nav class="rdturns${a?'':' rdturns-one'}" aria-label="Turn the page">${a}${b}</nav>`}
K.pager=pager;

/* the Hall of Doors' storybook: each page has its night painting (an edit of the day page, lined up with it). The page's own
   code swaps any picture that carries data-nsrc with the light; here each page is given its night painting */
const BN=(window.CC_RD_IMG||{}).book_n||{};
function bookNight(){if(!Object.keys(BN).length)return;document.querySelectorAll('img').forEach(i=>{if(i.dataset.nsrc)return;
 const u=i.getAttribute('src')||i.dataset.src||'',m=/book-(hw-\d-[a-z]+)\.[0-9a-f]{10}\./.exec(u);if(!m||!BN[m[1]])return;i.dataset.nsrc=BN[m[1]];
 if(i.getAttribute('src')&&!i.dataset.src){i.dataset.dsrc=i.getAttribute('src');if(K.R.classList.contains('ccdark'))i.src=i.dataset.nsrc}})}
bookNight();{const o=K.onRender;K.onRender=(k,r)=>{if(o)o(k,r);bookNight()}}

/* the chapters' own banners (drawn by the page's own code) take the sharper copy on big or high-density screens */
window.ccBX=(k,src,n)=>{if(!K.bigPic())return src;const S=window.CC_SEASON;
 if(S&&(S.ban||[]).indexOf(k)>=0){const X=(((K.XP.s||{})[S.id])||{})[n?'n':'d']||{};return X[k]||src}
 const X=(n?K.XP.n:K.XP.d)||{},M=(n?window.NIGHT:window.SCENES)||{};return X[k]&&src===M[k]?X[k]:src};
})();

window.ccRdBoot&&window.ccRdBoot();
